from solution import get_closest_vowel
import pytest
from hypothesis import given, HealthCheck
import hypothesis.strategies as st

VOWELS = set("AEIOUaeiou")
LETTERS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"

def _reference(word):
    vowels = set("AEIOUaeiou")
    # only interior indices 1 .. len-2 can qualify
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels and word[i - 1] not in vowels and word[i + 1] not in vowels:
            return word[i]
    return ""


# ---- concrete examples from the spec ----
def test_example_yogurt():
    assert get_closest_vowel("yogurt") == "u"

def test_example_FULL():
    assert get_closest_vowel("FULL") == "U"

def test_example_quick():
    assert get_closest_vowel("quick") == ""

def test_example_ab():
    assert get_closest_vowel("ab") == ""


# ---- explicit edge examples derived from spec ----
def test_empty_string_returns_empty():
    assert get_closest_vowel("") == ""

def test_single_vowel_returns_empty():
    assert get_closest_vowel("a") == ""
    assert get_closest_vowel("E") == ""

def test_single_consonant_returns_empty():
    assert get_closest_vowel("b") == ""
    assert get_closest_vowel("Z") == ""

def test_length_two_always_empty():
    assert get_closest_vowel("ba") == ""
    assert get_closest_vowel("ab") == ""
    assert get_closest_vowel("aa") == ""
    assert get_closest_vowel("bb") == ""

def test_vowel_at_beginning_does_not_count():
    # 'a' at index 0 must not count even though followed by consonant
    assert get_closest_vowel("abB") == ""
    assert get_closest_vowel("aBC") == ""

def test_vowel_at_ending_does_not_count():
    # trailing vowel must not count even though preceded by consonant
    assert get_closest_vowel("bBA") == ""
    assert get_closest_vowel("CBa") == ""
    assert get_closest_vowel("bca") == ""

def test_middle_vowel_between_consonants_counts():
    assert get_closest_vowel("bab") == "a"
    assert get_closest_vowel("bac") == "a"
    assert get_closest_vowel("BAB") == "A"

def test_all_vowels_returns_empty():
    assert get_closest_vowel("aeiou") == ""
    assert get_closest_vowel("AEIOU") == ""
    assert get_closest_vowel("aei") == ""

def test_all_consonants_returns_empty():
    assert get_closest_vowel("bcdfg") == ""
    assert get_closest_vowel("BCDFG") == ""
    assert get_closest_vowel("y") == ""
    assert get_closest_vowel("xyz") == ""

def test_returns_rightmost_not_leftmost():
    # two qualifying vowels: rightmost is at index 3
    assert get_closest_vowel("cacac") == "a"
    assert get_closest_vowel("babeb") == "e"
    # leftmost would be 'a', rightmost is 'e'
    assert get_closest_vowel("bacab") == _reference("bacab")
    assert _reference("bacab") == "a"  # sanity: rightmost qualifying
    assert get_closest_vowel("bAbEb") == "E"

def test_case_sensitive_vowel_match():
    assert get_closest_vowel("bAb") == "A"
    assert get_closest_vowel("bab") == "a"
    assert get_closest_vowel("bEb") == "E"
    assert get_closest_vowel("bOb") == "O"

def test_vowel_flanked_by_vowel_does_not_count():
    # 'u' in quick flanked by vowel on one side -> ""
    assert get_closest_vowel("quack") == "a"
    assert get_closest_vowel("quick") == ""
    assert get_closest_vowel("aeab") == ""
    assert get_closest_vowel("baei") == ""


# ---- property-based tests ----
@given(st.text(alphabet=LETTERS, min_size=0, max_size=12))
def test_property_result_is_empty_or_vowel_in_word(word):
    r = get_closest_vowel(word)
    assert isinstance(r, str)
    assert r == "" or (len(r) == 1 and r in VOWELS)

@given(st.text(alphabet=LETTERS, min_size=0, max_size=12))
def test_property_result_occurs_between_two_consonants(word):
    r = get_closest_vowel(word)
    if r == "":
        return
    # there must exist an interior index with that vowel flanked by consonants
    found = False
    for i in range(1, len(word) - 1):
        if word[i] == r and word[i - 1] not in VOWELS and word[i + 1] not in VOWELS:
            found = True
            break
    assert found, f"{r!r} not found between consonants in {word!r}"

@given(st.text(alphabet=LETTERS, min_size=0, max_size=12))
def test_property_result_is_rightmost_qualifying(word):
    r = get_closest_vowel(word)
    if r == "":
        # no interior vowel may be flanked by consonants
        for i in range(1, len(word) - 1):
            if word[i] in VOWELS and word[i - 1] not in VOWELS and word[i + 1] not in VOWELS:
                pytest.fail(f"missed qualifying vowel at {i} in {word!r}")
    else:
        # locate the returned occurrence from the right and ensure nothing qualifies to its right
        idx = -1
        for i in range(len(word) - 2, 0, -1):
            if word[i] == r and word[i - 1] not in VOWELS and word[i + 1] not in VOWELS:
                idx = i
                break
        assert idx != -1, f"returned {r!r} does not qualify in {word!r}"
        for j in range(idx + 1, len(word) - 1):
            # j is strictly to the right of chosen index but still interior
            # (index len-1 is ending and can never qualify)
            if word[j] in VOWELS and word[j - 1] not in VOWELS and word[j + 1] not in VOWELS:
                pytest.fail(f"not rightmost: {r!r} at {idx}, but {word[j]!r} qualifies at {j} in {word!r}")

@given(st.text(alphabet=LETTERS, min_size=0, max_size=12))
def test_property_equivalence_to_reference_model(word):
    assert get_closest_vowel(word) == _reference(word)

@given(st.text(alphabet=LETTERS, min_size=0, max_size=2))
def test_property_short_words_always_empty(word):
    # beginning and ending don't count, so len <= 2 has no interior index
    assert get_closest_vowel(word) == ""

@given(st.text(alphabet=LETTERS, min_size=3, max_size=12))
def test_property_ending_vowel_never_returned_as_last_char(word):
    # construct word ending with a vowel preceded by consonant; ending itself must not be returned
    w = word[:-1] + "a" if word[-2] not in VOWELS else word[:-1] + "a"
    r = get_closest_vowel(w)
    if r != "":
        assert r != w[-1] or any(
            w[i] == r and w[i - 1] not in VOWELS and w[i + 1] not in VOWELS
            for i in range(1, len(w) - 1)
        )
    # strongest check: if the only vowel is the final char, result must be ""
    if all(c not in VOWELS for c in w[:-1]):
        assert get_closest_vowel(w) == ""
